def canJump(nums):
    farthest = 0  # 当前能到达的最远下标
    for i, x in enumerate(nums):
        if i > farthest:
            return False  # 断链，走不到这里
        farthest = max(farthest, i + x)
    return True

def merge(intervals):
    intervals.sort(key=lambda r: r[0])  # 按左端排序
    res = []
    for s, e in intervals:
        if res and s <= res[-1][1]:  # 与末区间重叠
            res[-1][1] = max(res[-1][1], e)
        else:
            res.append([s, e])
    return res
